";s:0:\"\";s:11:\"orientation\";s:1:\"0\";s:8:\"keywords\";a:0:{}}}'),(1231,216,'_thumbnail_id','217'),(1232,191,'careers_openings','a:4:{i:0;a:6:{s:9:\"job_title\";s:58:\"Kỹ sư Nghiên cứu & Phát triển Sơn Công nghiệp\";s:10:\"department\";s:3:\"R&D\";s:8:\"location\";s:13:\"Bình Dương\";s:15:\"employment_type\";s:17:\"Toàn thời gian\";s:8:\"deadline\";s:10:\"30/06/2026\";s:11:\"description\";s:1102:\"<h4>Mô tả công việc</h4>\r\n<ul>\r\n<li>Nghiên cứu và phát triển công thức sơn epoxy, polyurethane, và water-based mới</li>\r\n<li>Kiểm tra chất lượng sản phẩm theo tiêu chuẩn ISO, ASTM</li>\r\n<li>Hợp tác với bộ phận kỹ thuật để tối ưu hóa quy trình sản xuất</li>\r\n<li>Theo dõi xu hướng công nghệ sơn và nguyên liệu mới trên thị trường</li>\r\n</ul>\r\n<h4>Yêu cầu</h4>\r\n<ul>\r\n<li>Tốt nghiệp Đại học chuyên ngành Hóa học, Công nghệ Hóa học, hoặc Vật liệu</li>\r\n<li>Ít nhất 3 năm kinh nghiệm trong lĩnh vực R&D sơn công nghiệp</li>\r\n<li>Thành thạo các phương pháp kiểm tra: độ bám dính, độ bền muối, QUV, độ cứng</li>\r\n<li>Tiếng Anh giao tiếp tốt (đọc tài liệu kỹ thuật)</li>\r\n</ul>\r\n<h4>Quyền lợi</h4>\r\n<ul>\r\n<li>Lương cạnh tranh 20-35 triệu VNĐ, thưởng KPI hàng quý</li>\r\n<li>Bảo hiểm sức khỏe toàn diện cho bản thân và gia đình</li>\r\n<li>Cơ hội đào tạo tại nước ngoài (Đức, Nhật Bản)</li>\r\n</ul>\";}i:1;a:6:{s:9:\"job_title\";s:51:\"Nhân viên Kinh doanh B2B — Khu vực Miền Nam\";s:10:\"department\";s:5:\"Sales\";s:8:\"location\";s:18:\"TP. Hồ Chí Minh\";s:15:\"employment_type\";s:17:\"Toàn thời gian\";s:8:\"deadline\";s:10:\"15/05/2026\";s:11:\"description\";s:985:\"<h4>Mô tả công việc</h4>\r\n<ul>\r\n<li>Phát triển và duy trì mối quan hệ khách hàng B2B: nhà thầu, chủ đầu tư, KCN</li>\r\n<li>Tư vấn giải pháp sơn công nghiệp phù hợp với yêu cầu dự án</li>\r\n<li>Đạt chỉ tiêu doanh số hàng tháng/quý</li>\r\n<li>Phối hợp với bộ phận kỹ thuật hỗ trợ khách hàng tại công trường</li>\r\n</ul>\r\n<h4>Yêu cầu</h4>\r\n<ul>\r\n<li>Tốt nghiệp Đại học chuyên ngành Kinh doanh, Hóa học, hoặc Xây dựng</li>\r\n<li>2+ năm kinh nghiệm kinh doanh B2B (ưu tiên ngành sơn/vật liệu xây dựng)</li>\r\n<li>Có xe ô tô cá nhân và sẵn sàng đi công tác thường xuyên</li>\r\n<li>Kỹ năng thuyết trình và đàm phán tốt</li>\r\n</ul>\r\n<h4>Quyền lợi</h4>\r\n<ul>\r\n<li>Lương cơ bản + hoa hồng hấp dẫn (không giới hạn)</li>\r\n<li>Hỗ trợ xăng xe, điện thoại, tiếp khách</li>\r\n<li>Du lịch team-building 2 lần/năm</li>\r\n</ul>\";}i:2;a:6:{s:9:\"job_title\";s:52:\"Kỹ thuật viên Thi công — Sơn Công nghiệp\";s:10:\"department\";s:9:\"Technical\";s:8:\"location\";s:32:\"TP. Hồ Chí Minh & Các tỉnh\";s:15:\"employment_type\";s:17:\"Toàn thời gian\";s:8:\"deadline\";s:10:\"30/04/2026\";s:11:\"description\";s:772:\"<h4>Mô tả công việc</h4>\r\n<ul>\r\n<li>Hỗ trợ kỹ thuật thi công sơn tại công trường cho khách hàng</li>\r\n<li>Đào tạo đội ngũ thi công của nhà thầu về quy trình và kỹ thuật</li>\r\n<li>Giám sát chất lượng thi công, kiểm tra DFT, độ bám dính</li>\r\n<li>Lập báo cáo kỹ thuật và đề xuất giải pháp xử lý sự cố</li>\r\n</ul>\r\n<h4>Yêu cầu</h4>\r\n<ul>\r\n<li>Tốt nghiệp Cao đẳng/Đại học chuyên ngành Hóa, Xây dựng, hoặc tương đương</li>\r\n<li>1+ năm kinh nghiệm thi công hoặc giám sát sơn công nghiệp</li>\r\n<li>Sử dụng thành thạo thiết bị kiểm tra: Elcometer, DFT gauge, pull-off tester</li>\r\n<li>Sẵn sàng đi công tác 50-70% thời gian</li>\r\n</ul>\";}i:3;a:6:{s:9:\"job_title\";s:47:\"Nhân viên QC — Kiểm soát Chất lượng\";s:10:\"department\";s:15:\"Quality Control\";s:8:\"location\";s:13:\"Bình Dương\";s:15:\"employment_type\";s:17:\"Toàn thời gian\";s:8:\"deadline\";s:10:\"31/05/2026\";s:11:\"description\";s:664:\"<h4>Mô tả công việc</h4>\r\n<ul>\r\n<li>Kiểm tra chất lượng nguyên liệu đầu vào và thành phẩm theo SOP</li>\r\n<li>Thực hiện các phép kiểm tra: viscosity, fineness of grind, hiding power, color match</li>\r\n<li>Quản lý hồ sơ COA (Certificate of Analysis) cho từng lô sản xuất</li>\r\n<li>Phối hợp R&D xử lý sản phẩm không đạt yêu cầu</li>\r\n</ul>\r\n<h4>Yêu cầu</h4>\r\n<ul>\r\n<li>Tốt nghiệp Đại học ngành Hóa học hoặc Công nghệ Hóa học</li>\r\n<li>1-2 năm kinh nghiệm QC (ưu tiên ngành sơn, mực in, keo dán)</li>\r\n<li>Tỉ mỉ, trung thực, và có tư duy hệ thống</li>\r\n</ul>\";}}'),(1233,191,'careers_contact_email','hr@alkana.vn'),(1234,174,'product_specs','a:7:{i:0;a:3:{s:10:\"spec_label\";s:24:\"Độ phủ lý thuyết\";s:10:\"spec_value\";s:20:\"4 – 5 m²/bao 25kg\";s:9:\"spec_unit\";s:0:\"\";}i:1;a:3:{s:10:\"spec_label\";s:20:\"Tỷ lệ pha trộn\";s:10:\"spec_value\";s:40:\"Trộn với 6–7 lít nước/bao 25kg\";s:9:\"spec_unit\";s:0:\"\";}i:2;a:3:{s:10:\"spec_label\";s:13:\"Dung môi pha\";s:10:\"spec_value\";s:14:\"Nước sạch\";s:9:\"spec_unit\";s:0:\"\";}i:3;a:3:{s:10:\"spec_label\";s:10:\"Lớp sơn\";s:10:\"spec_value\";s:6:\"filler\";s:9:\"spec_unit\";s:0:\"\";}i:4;a:3:{s:10:\"spec_label\";s:18:\"Khô sờ được\";s:10:\"spec_value\";s:21:\"3 giờ (tại 30°C)\";s:9:\"spec_unit\";s:0:\"\";}i:5;a:3:{s:10:\"spec_label\";s:11:\"Khô cứng\";s:10:\"spec_value\";s:22:\"24 giờ (tại 30°C)\";s:9:\"spec_unit\";s:0:\"\";}i:6;a:3:{s:10:\"spec_label\";s:17:\"Sơn lớp tiếp\";s:10:\"spec_value\";s:17:\"Không áp dụng\";s:9:\"spec_unit\";s:0:\"\";}}'),(1235,172,'product_specs','a:7:{i:0;a:3:{s:10:\"spec_label\";s:24:\"Độ phủ lý thuyết\";s:10:\"spec_value\";s:22:\"6 – 8 m²/lít/lớp\";s:9:\"spec_unit\";s:0:\"\";}i:1;a:3:{s:10:\"spec_label\";s:20:\"Tỷ lệ pha trộn\";s:10:\"spec_value\";s:25:\"4:1 theo trọng lượng\";s:9:\"spec_unit\";s:0:\"\";}i:2;a:3:{s:10:\"spec_label\";s:13:\"Dung môi pha\";s:10:\"spec_value\";s:32:\"Alkana PU Thinner No.7 (5–10%)\";s:9:\"spec_unit\";s:0:\"\";}i:3;a:3:{s:10:\"spec_label\";s:10:\"Lớp sơn\";s:10:\"spec_value\";s:7:\"topcoat\";s:9:\"spec_unit\";s:0:\"\";}i:4;a:3:{s:10:\"spec_label\";s:18:\"Khô sờ được\";s:10:\"spec_value\";s:21:\"3 giờ (tại 30°C)\";s:9:\"spec_unit\";s:0:\"\";}i:5;a:3:{s:10:\"spec_label\";s:11:\"Khô cứng\";s:10:\"spec_value\";s:22:\"12 giờ (tại 30°C)\";s:9:\"spec_unit\";s:0:\"\";}i:6;a:3:{s:10:\"spec_l