INSERT INTO `wp_posts` VALUES (1,1,'2026-03-05 06:57:27','2026-03-05 06:57:27','<!-- wp:paragraph -->\n<p>Welcome to WordPress. This is your first post. Edit or delete it, then start writing!</p>\n<!-- /wp:paragraph -->','Hello world!','','publish','open','open','','hello-world','','','2026-03-05 06:57:27','2026-03-05 06:57:27','',0,'http://localhost/alkana-wp/?p=1',0,'post','',1),(2,1,'2026-03-05 06:57:27','2026-03-05 06:57:27','<!-- wp:paragraph -->\n<p>This is an example page. It\'s different from a blog post because it will stay in one place and will show up in your site navigation (in most themes). Most people start with an About page that introduces them to potential site visitors. It might say something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>Hi there! I\'m a bike messenger by day, aspiring actor by night, and this is my website. I live in Los Angeles, have a great dog named Jack, and I like pi&#241;a coladas. (And gettin\' caught in the rain.)</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>...or something like this:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:quote -->\n<blockquote class=\"wp-block-quote\">\n<!-- wp:paragraph -->\n<p>The XYZ Doohickey Company was founded in 1971, and has been providing quality doohickeys to the public ever since. Located in Gotham City, XYZ employs over 2,000 people and does all kinds of awesome things for the Gotham community.</p>\n<!-- /wp:paragraph -->\n</blockquote>\n<!-- /wp:quote -->\n\n<!-- wp:paragraph -->\n<p>As a new WordPress user, you should go to <a href=\"http://localhost/alkana-wp/wp-admin/\">your dashboard</a> to delete this page and create new pages for your content. Have fun!</p>\n<!-- /wp:paragraph -->','Sample Page','','publish','closed','open','','sample-page','','','2026-03-05 06:57:27','2026-03-05 06:57:27','',0,'http://localhost/alkana-wp/?page_id=2',0,'page','',0),(3,1,'2026-03-05 06:57:27','2026-03-05 06:57:27','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we are</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Our website address is: http://localhost/alkana-wp.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Comments</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>When visitors leave comments on the site we collect the data shown in the comments form, and also the visitor&#8217;s IP address and browser user agent string to help spam detection.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>An anonymized string created from your email address (also called a hash) may be provided to the Gravatar service to see if you are using it. The Gravatar service privacy policy is available here: https://automattic.com/privacy/. After approval of your comment, your profile picture is visible to the public in the context of your comment.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Media</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you upload images to the website, you should avoid uploading images with embedded location data (EXIF GPS) included. Visitors to the website can download and extract any location data from images on the website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Cookies</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment on our site you may opt-in to saving your name, email address and website in cookies. These are for your convenience so that you do not have to fill in your details again when you leave another comment. These cookies will last for one year.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you visit our login page, we will set a temporary cookie to determine if your browser accepts cookies. This cookie contains no personal data and is discarded when you close your browser.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>When you log in, we will also set up several cookies to save your login information and your screen display choices. Login cookies last for two days, and screen options cookies last for a year. If you select &quot;Remember Me&quot;, your login will persist for two weeks. If you log out of your account, the login cookies will be removed.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>If you edit or publish an article, an additional cookie will be saved in your browser. This cookie includes no personal data and simply indicates the post ID of the article you just edited. It expires after 1 day.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Embedded content from other websites</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Articles on this site may include embedded content (e.g. videos, images, articles, etc.). Embedded content from other websites behaves in the exact same way as if the visitor has visited the other website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>These websites may collect data about you, use cookies, embed additional third-party tracking, and monitor your interaction with that embedded content, including tracking your interaction with the embedded content if you have an account and are logged in to that website.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Who we share your data with</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you request a password reset, your IP address will be included in the reset email.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">How long we retain your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you leave a comment, the comment and its metadata are retained indefinitely. This is so we can recognize and approve any follow-up comments automatically instead of holding them in a moderation queue.</p>\n<!-- /wp:paragraph -->\n<!-- wp:paragraph -->\n<p>For users that register on our website (if any), we also store the personal information they provide in their user profile. All users can see, edit, or delete their personal information at any time (except they cannot change their username). Website administrators can also see and edit that information.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">What rights you have over your data</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>If you have an account on this site, or have left comments, you can request to receive an exported file of the personal data we hold about you, including any data you have provided to us. You can also request that we erase any personal data we hold about you. This does not include any data we are obliged to keep for administrative, legal, or security purposes.</p>\n<!-- /wp:paragraph -->\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Where your data is sent</h2>\n<!-- /wp:heading -->\n<!-- wp:paragraph -->\n<p><strong class=\"privacy-policy-tutorial\">Suggested text: </strong>Visitor comments may be checked through an automated spam detection service.</p>\n<!-- /wp:paragraph -->\n','Privacy Policy','','draft','closed','open','','privacy-policy','','','2026-03-05 06:57:27','2026-03-05 06:57:27','',0,'http://localhost/alkana-wp/?page_id=3',0,'page','',0),(4,0,'2026-03-05 06:57:29','2026-03-05 06:57:29','<!-- wp:page-list /-->','Navigation','','publish','closed','closed','','navigation','','','2026-03-05 06:57:29','2026-03-05 06:57:29','',0,'http://localhost/alkana-wp/index.php/2026/03/05/navigation/',0,'wp_navigation','',0),(14,0,'2026-03-05 08:51:04','2026-03-05 08:51:04','','Trang chủ','','publish','closed','closed','','trang-chu','','','2026-03-05 08:51:04','2026-03-05 08:51:04','',0,'http://localhost/alkana-wp/index.php/trang-chu/',0,'page','',0),(15,0,'2026-03-05 08:51:04','2026-03-05 08:51:04','','Tin tức','','publish','closed','closed','','tin-tuc','','','2026-03-05 08:51:04','2026-03-05 08:51:04','',0,'http://localhost/alkana-wp/index.php/tin-tuc/',0,'page','',0),(42,0,'2026-03-31 03:50:13','2026-03-31 03:50:13','','Alkana Hero — Industrial Steel Structure','','inherit','open','closed','','alkana-hero-industrial-steel-structure','','','2026-03-31 03:50:13','2026-03-31 03:50:13','',14,'http://localhost/alkana-wp/wp-content/uploads/2026/03/Alkana-Hero-—-Industrial-Steel-Structure.jpg',0,'attachment','image/jpeg',0),(44,0,'2026-03-31 03:50:14','2026-03-31 03:50:14','','Alkana Epoxy Primer EP-10','','inherit','open','closed','','alkana-epoxy-primer-ep-10-2','','','2026-03-31 03:50:14','2026-03-31 03:50:14','',0,'http://localhost/alkana-wp/wp-content/uploads/2026/03/Alkana-Epoxy-Primer-EP-10.jpg',0,'attachment','image/jpeg',0),(47,0,'2026-03-31 03:50:16','2026-03-31 03:50:16','','Alkana WaterGuard 500','','inherit','open','closed','','alkana-waterguard-500-2','','','2026-03-31 03:50:16','2026-03-31 03:50:16','',0,'http://localhost/alkana-wp/wp-content/uploads/2026/03/Alkana-WaterGuard-500.jpg',0,'attachment','image/jpeg',0),(49,0,'2026-03-31 03:50:20','2026-03-31 03:50:20','','Alkana FloorShield EF-300','','inherit','open','closed','','alkana-floorshield-ef-300-2','','','2026-03-31 03:50:20','2026-03-31 03:50:20','',0,'http://localhost/alkana-wp/wp-content/uploads/2026/03/Alkana-FloorShield-EF-300.jpg',0,'attachment','image/jpeg',0),(52,0,'2026-03-31 03:50:22','2026-03-31 03:50:22','','Alkana Anti-Rust AR-15','','inherit','open','closed','','alkana-a